"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["45760"],{6076(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.ordem_invalida","status":422,"titulo":"A ordem do item n\xe3o pode ser negativa"},"descricao":{"codigo":"uniplus.item_formulario.ordem_invalida","requisitos":[],"oQueAconteceu":["A `ordem` de um item do formul\xe1rio, ou de um campo de grupo, \xe9 negativa. A ordem \xe9 a posi\xe7\xe3o do item na coleta, e n\xe3o pode ser negativa. A mensagem \xe9 \\"A ordem do item n\xe3o pode ser negativa.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `itens[i].ordem` ou, no campo de um grupo, `grupos[g].subitens[j].ordem`; nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`. Cada item recusado tem a pr\xf3pria entrada, junto das demais recusas da forma do item, e nada \xe9 gravado.","No formul\xe1rio de inscri\xe7\xe3o, e no modelo que serve \xe0 fase de inscri\xe7\xe3o, a ordem dos itens e dos grupos que n\xe3o s\xe3o dados b\xe1sicos do candidato \xe9 deslocada para depois da se\xe7\xe3o reservada dos dados b\xe1sicos antes desta confer\xeancia, de modo que a ordem negativa de um item desse formul\xe1rio n\xe3o chega a ser recusada aqui; o campo de um grupo, que tem ordem pr\xf3pria dentro do grupo, n\xe3o \xe9 deslocado. Nos formul\xe1rios de isen\xe7\xe3o de taxa e de habilita\xe7\xe3o, e nos modelos que n\xe3o servem \xe0 fase de inscri\xe7\xe3o, a ordem negativa do item \xe9 recusada. Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Informe `ordem` com 0 ou um n\xfamero positivo, sem repetir a ordem de outro item ou grupo do mesmo formul\xe1rio."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);